-- Freeze generated bytes and revision selection across attempts of one work item.
create table garmin.report_publications (
 user_id uuid not null, connection_id uuid not null, report_date text not null, scope text not null,
 revision bigint not null, created_at timestamptz not null default now(),
 primary key(user_id,connection_id,report_date,scope,revision),
 foreign key(user_id,connection_id,report_date,scope,revision)
   references garmin.evaluation_revisions(user_id,connection_id,report_date,scope,revision)
);
create table garmin.report_publication_items (
 user_id uuid not null, connection_id uuid not null, report_date text not null, scope text not null,
 revision bigint not null, name text not null, kind text not null check(kind in ('report','graph')),
 media_type text not null, content bytea not null, request_id uuid not null,
 primary key(user_id,connection_id,report_date,scope,revision,name),
 foreign key(user_id,connection_id,report_date,scope,revision)
   references garmin.report_publications(user_id,connection_id,report_date,scope,revision)
);
create table garmin.report_work_revisions (
 work_id uuid not null, user_id uuid not null, connection_id uuid not null, report_date text not null,
 scope text not null, revision bigint not null,
 primary key(work_id,report_date,scope),
 foreign key(user_id,connection_id,report_date,scope,revision)
   references garmin.evaluation_revisions(user_id,connection_id,report_date,scope,revision)
);
-- A scheduled retry can finish a previously collected day after projection repair.
create table garmin.collect_work_runs (
 work_id uuid not null, user_id uuid not null, connection_id uuid not null, local_date text not null, run_id bigint not null,
 primary key(work_id,local_date),
 foreign key(user_id,connection_id,run_id) references garmin.run(user_id,connection_id,id)
);
-- The document represents the complete selected revision vector, not only day.
create table garmin.report_bundle_files (
 user_id uuid not null, connection_id uuid not null, report_date text not null,
 revision_key text not null, day_revision bigint not null, content bytea not null,
 request_id uuid not null, created_at timestamptz not null default now(),
 primary key(user_id,connection_id,report_date,revision_key)
);
